<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {can,projectId} from '@/core/session'
import {ApiError,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import ReferenceIcon from '@/ui/ReferenceIcon.vue'
import RuleActionDeviceTarget,{type RuleActionDeviceTarget as Target} from './RuleActionDeviceTarget.vue'
import {readDeviceAlarmRules,type DeviceAlarmRule} from '../devices/device-alarm-rules-api'
import {findAutomationAlarmRule,automationAlarmRuleStateLabel} from './automation-alarm-rule-choices'
import {automationAlarmCondition,automationAlarmConditionAction,automationAlarmConditionPresentation,type AutomationNode} from './automation-editor-draft'
const props=defineProps<{condition?:AutomationNode;disabled?:boolean}>(),emit=defineEmits<{save:[node:AutomationNode,deviceName:string,ruleName:string];cancel:[];denied:[cause:ApiError]}>()
const initial=props.condition?automationAlarmCondition(props.condition):undefined,enabled=ref(initial?.enabled??true),device=ref<Target>(),deviceId=ref(initial?.deviceId??''),ruleId=ref(initial?.alarmRuleId??''),alarmState=ref<'alerting'|'ok'>(initial?.alarmState??'alerting')
const rules=ref<DeviceAlarmRule[]>([]),original=ref<DeviceAlarmRule>(),page=ref(0),total=ref<string>(),loading=ref(false),targetBusy=ref(false),error=ref('')
const readable=computed(()=>can('rule:manage')&&can('device:read')&&can('alarm:read')&&!!projectId.value),blocked=computed(()=>props.disabled||!readable.value)
const options=computed(()=>original.value&&!rules.value.some(row=>row.id===original.value!.id)?[original.value,...rules.value]:rules.value),selectedRule=computed(()=>options.value.find(row=>row.id===ruleId.value)),hasMore=computed(()=>total.value!==undefined&&BigInt(page.value)*24n<BigInt(total.value))
let alive=true,turn=0,applied=false,controller:AbortController|undefined
function reset(){turn++;controller?.abort();device.value=undefined;deviceId.value='';ruleId.value='';rules.value=[];original.value=undefined;page.value=0;total.value=undefined;loading.value=false;targetBusy.value=false;error.value=''}
function current(token:number,project:string,epoch:number,id:string){return alive&&token===turn&&project===projectId.value&&epoch===identityEpoch()&&id===deviceId.value&&readable.value}
async function loadPage(next:number,token:number,project:string,epoch:number,id:string,signal:AbortSignal){
 const value=await readDeviceAlarmRules(project,id,next,24,signal);if(!current(token,project,epoch,id)||signal.aborted)return false
 if(!Array.isArray(value.items)||typeof value.total!=='string'||total.value!==undefined&&value.total!==total.value)throw new Error('告警规则候选已变化，请重新读取')
 const known=new Set(rules.value.map(row=>row.id));if(value.items.some(row=>known.has(row.id)))throw new Error('告警规则候选已变化，请重新读取')
 rules.value=[...rules.value,...value.items];page.value=next;total.value=value.total;return true
}
async function selected(target:Target|undefined){
 const token=++turn;controller?.abort();rules.value=[];original.value=undefined;page.value=0;total.value=undefined;error.value='';loading.value=false;device.value=target
 if(!target){if(applied||!initial){deviceId.value='';ruleId.value=''}return}
 if(target.projectId!==projectId.value){deviceId.value='';ruleId.value='';error.value='请选择当前项目中的设备';return}
 const restore=!applied&&initial?.deviceId===target.id;applied=true;deviceId.value=target.id;ruleId.value=restore?initial!.alarmRuleId:''
 if(!readable.value)return;const project=projectId.value,epoch=identityEpoch(),id=target.id;controller=new AbortController();const signal=controller.signal;loading.value=true
 try{if(!await loadPage(1,token,project,epoch,id,signal))return;if(restore&&ruleId.value&&!rules.value.some(row=>row.id===ruleId.value)){const row=await findAutomationAlarmRule(project,id,ruleId.value,signal);if(!current(token,project,epoch,id))return;original.value=row;if(!row&&enabled.value)error.value='请选择告警规则'}}catch(cause){if(current(token,project,epoch,id)){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){rules.value=[];original.value=undefined;emit('denied',cause)}}}finally{if(current(token,project,epoch,id))loading.value=false}
}
async function more(){if(blocked.value||loading.value||!hasMore.value||!controller||!device.value)return;const token=turn,project=projectId.value,epoch=identityEpoch(),id=deviceId.value;loading.value=true;error.value='';try{await loadPage(page.value+1,token,project,epoch,id,controller.signal)}catch(cause){if(current(token,project,epoch,id)){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){rules.value=[];original.value=undefined;emit('denied',cause)}}}finally{if(current(token,project,epoch,id))loading.value=false}}
async function retry(){if(blocked.value||loading.value||!device.value)return;const wanted=ruleId.value,token=++turn,project=projectId.value,epoch=identityEpoch(),id=deviceId.value;controller?.abort();controller=new AbortController();const signal=controller.signal;rules.value=[];original.value=undefined;page.value=0;total.value=undefined;error.value='';loading.value=true;try{if(!await loadPage(1,token,project,epoch,id,signal))return;if(wanted&&!rules.value.some(row=>row.id===wanted)){const row=await findAutomationAlarmRule(project,id,wanted,signal);if(current(token,project,epoch,id))original.value=row}}catch(cause){if(current(token,project,epoch,id)){error.value=errorMessage(cause);if(cause instanceof ApiError&&[401,403,404].includes(cause.status)){rules.value=[];original.value=undefined;emit('denied',cause)}}}finally{if(current(token,project,epoch,id))loading.value=false}}
function chooseRule(id:unknown){if(blocked.value||loading.value)return;ruleId.value=typeof id==='string'&&options.value.some(row=>row.id===id)?id:''}
function save(){if(blocked.value||loading.value||targetBusy.value)return;try{if(!deviceId.value)throw new Error('请选择设备');if(!ruleId.value||enabled.value&&(!device.value||!selectedRule.value||error.value))throw new Error('请选择告警规则');emit('save',automationAlarmConditionAction({enabled:enabled.value,deviceId:deviceId.value,alarmRuleId:ruleId.value,alarmState:alarmState.value}),device.value?.name??deviceId.value,selectedRule.value?.name??ruleId.value)}catch(cause){error.value=errorMessage(cause)}}
watch([projectId,readable],()=>{reset();emit('cancel')});const dispose=onIdentityChange(()=>{reset();emit('cancel')});onScopeDispose(()=>{alive=false;turn++;controller?.abort();dispose()})
</script>
<template><el-dialog :model-value="true" :title="condition?'编辑条件':'配置条件'" width="800px" :lock-scroll="false" :close-on-click-modal="false" :close-on-press-escape="!disabled" :show-close="!disabled" append-to-body @update:model-value="!disabled&&emit('cancel')">
 <div class="automation-alarm-type"><span :style="{background:automationAlarmConditionPresentation.background,color:automationAlarmConditionPresentation.color}"><ReferenceIcon :glyph="automationAlarmConditionPresentation.glyph"/></span><div><strong>{{automationAlarmConditionPresentation.label}}</strong><p>{{automationAlarmConditionPresentation.description}}</p></div></div>
 <el-form v-if="readable" label-position="top" size="small" :disabled="blocked"><el-form-item label="启用条件"><el-switch v-model="enabled" aria-label="启用告警条件" :disabled="blocked"/></el-form-item><el-form-item label="选择设备"><RuleActionDeviceTarget :initial-id="initial?.deviceId" placeholder="请选择设备" :disabled="blocked" @selected="selected" @busy="targetBusy=$event"/></el-form-item>
 <template v-if="deviceId"><el-form-item label="选择告警规则"><el-select :model-value="ruleId" aria-label="选择告警规则" placeholder="请选择告警规则" filterable size="small" style="width:100%" :loading="loading" :disabled="blocked||loading||!options.length" @update:model-value="chooseRule"><el-option v-for="row in options" :key="row.id" :value="row.id" :label="row.name"><div class="alarm-rule-choice"><span>{{row.name}}</span><span class="alarm-rule-state">{{automationAlarmRuleStateLabel(row)}}</span></div></el-option></el-select><div v-if="!loading&&total==='0'" class="form-item-tip">该设备暂无告警规则</div><el-button v-if="hasMore" link size="small" :disabled="blocked||loading" @click="more">加载更多</el-button></el-form-item>
 <el-form-item v-if="ruleId" label="规则状态"><el-radio-group v-model="alarmState" aria-label="规则状态" :disabled="blocked"><el-radio value="alerting"><span>告警中</span><span class="alarm-state-tip">规则当前处于告警状态</span></el-radio><el-radio value="ok"><span>正常</span><span class="alarm-state-tip">规则当前处于正常状态</span></el-radio></el-radio-group></el-form-item></template></el-form>
 <el-alert v-if="error" :title="error" type="warning" :closable="false"><el-button v-if="device" link :disabled="blocked||loading" @click="retry">重新读取候选</el-button></el-alert>
 <template #footer><el-button :disabled="disabled" @click="emit('cancel')">取消</el-button><el-button type="primary" :disabled="blocked||loading||targetBusy" @click="save">确定</el-button></template>
</el-dialog></template>
<style scoped>.automation-alarm-type{display:flex;align-items:center;gap:14px;padding:14px 16px;background:#f8f9fa;border-radius:8px;margin-bottom:20px}.automation-alarm-type>span{display:flex;align-items:center;justify-content:center;width:42px;height:42px;border-radius:10px;flex:none;font-size:22px}.automation-alarm-type strong{font-size:15px;font-weight:600;color:#333}.automation-alarm-type p{font-size:13px;color:#888;margin:4px 0 0}.alarm-rule-choice{display:flex;justify-content:space-between;align-items:center;gap:8px}.alarm-rule-state{color:#9ca3af;font-size:12px}.alarm-state-tip{color:#6b7280;font-size:12px;margin-left:8px}.form-item-tip{font-size:13px;color:#909399;margin-top:8px;line-height:1.4}</style>
